'use strict';
/**
 * Seed catalogue. Every record is seeded as `pending_review`: it was compiled on
 * 2026-11-14 from official portals and recent public reporting, and must be
 * verified by a HaqSetu reviewer (Admin → Verification queue) before it is marked
 * `verified`. Amounts and rules change — the official link is always authoritative.
 *
 * Rule helpers keep the records readable. See src/eligibility.js for semantics.
 */
const R = {
  age: (min, max) => (max == null ? { field: 'age', op: 'gte', value: min } : min == null ? { field: 'age', op: 'lte', value: max } : { field: 'age', op: 'between', value: [min, max] }),
  female: () => ({ field: 'gender', op: 'eq', value: 'female', label: 'Applicant is a woman' }),
  incomeMax: (n, label) => ({ field: 'annual_income', op: 'lte', value: n, ...(label ? { label } : {}) }),
  yes: (field, label, extra = {}) => ({ field, op: 'is', value: true, ...(label ? { label } : {}), ...extra }),
  no: (field, label, extra = {}) => ({ field, op: 'is', value: false, ...(label ? { label } : {}), ...extra }),
  in: (field, value, label) => ({ field, op: 'in', value, ...(label ? { label } : {}) }),
  manual: (label) => ({ field: '__manual', op: 'manual', label }),
  any: (...nodes) => ({ any: nodes }),
};
const POST_MATRIC = ['higher_secondary', 'diploma', 'undergraduate', 'postgraduate', 'doctorate'];
const MS = 'https://www.myscheme.gov.in/search?q=';

